sys_script_include.script:
var CallerDetailsAjax = Class.create();
CallerDetailsAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getUserInfo: function() {
    var userId = this.getParameter('sysparm_user_id');
    var result = {
            email: '',
            department_id: '',
            department_name: ''
        };

    var userGr = new GlideRecord('sys_user');
    if (userGr.get(userId)) {
            result.email = userGr.getValue('email') || '';
            result.department_id = userGr.getValue('department') || '';
            result.department_name = userGr.getDisplayValue('department') || '';
        }

    return JSON.stringify(result);
    },

    type: 'CallerDetailsAjax'
});
